int handle_packet(struct conn *c, const char *payload, size_t len) {
    char name[32];
    char *buf = malloc(c->count * c->item_size);
    if (!buf)
        return -1;
    strcpy(name, payload);              /* attacker controls payload */
    memcpy(buf, payload + 4, len);      /* len never checked */
    for (int i = 0; i <= c->count; i++)
        buf[i + 1] = name[i];
    printf(name);
    free(buf);
    log_packet(c, buf);
    return 0;
}

static TRBCCode xhci_disable_ep(XHCIState *xhci, unsigned int slotid,
                               unsigned int epid)
{
    XHCISlot *slot;
    XHCIEPContext *epctx;
    int i;
    trace_usb_xhci_ep_disable(slotid, epid);
    assert(slotid >= 1 && slotid <= xhci->numslots);
    assert(epid >= 1 && epid <= 31);
    slot = &xhci->slots[slotid-1];
    if (!slot->eps[epid-1]) {
        DPRINTF("xhci: slot %d ep %d already disabled\n", slotid, epid);
        return CC_SUCCESS;
    xhci_ep_nuke_xfers(xhci, slotid, epid);
    epctx = slot->eps[epid-1];
    if (epctx->nr_pstreams) {
        xhci_free_streams(epctx);
    xhci_set_ep_state(xhci, epctx, NULL, EP_DISABLED);
    timer_free(epctx->kick_timer);
    g_free(epctx);
    slot->eps[epid-1] = NULL;
    return CC_SUCCESS;

