static int copy_name(char *dst, size_t dst_len, const char *src) {
    if (dst == NULL || src == NULL || dst_len == 0)
        return -1;
    size_t n = strnlen(src, dst_len - 1);
    memcpy(dst, src, n);
    dst[n] = '\0';
    return (int)n;
}
